llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Ethinylestradiol, a rigid phenolic steroid with extensive first-pass metabolism, has absolute oral bioavailability of 40–50% in humans, supporting that a rigid phenolic opioid-like molecule can exceed 20% despite presystemic clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Codeine, a morphinan with an N-methyl group and 3-substitution, has oral bioavailability of 80.5% in healthy subjects, directly supporting high oral bioavailability for the morphinan scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Norethisterone, a rigid steroid-like molecule with a ketone and low molecular weight, has absolute oral bioavailability around 64%, supporting that rigid, low-MW structures with first-pass metabolism can still achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Meptazinol, a phenolic tertiary amine, has absolute oral bioavailability of only 4.5% in humans due to extensive first-pass metabolism, providing contradictory evidence that a phenol plus basic amine can lead to low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pentazocine, a phenolic benzomorphan opioid structurally close to the query, has mean absolute oral bioavailability of about 18%, just below the 20% threshold, providing contradictory evidence for a closely related opioid scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is hydromorphone, a rigid morphinan with a phenol, ketone, and N-methyl tertiary amine. The most transferable supportive evidence includes codeine, a morphinan with high oral bioavailability (80.5%), and rigid phenolic/steroid analogues such as ethinylestradiol and norethisterone that exceed 20% despite first-pass metabolism. The low-F analogues meptazinol and pentazocine are relevant, but meptazinol is less structurally aligned and pentazocine falls only slightly below the threshold. Overall, the balance of high-transfer experimental evidence and the known physicochemical profile support F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for hydromorphone is present in the provided evidence; the decision relies on analogue transfer.",
    "The low-F analogues with phenol and tertiary amine (meptazinol, pentazocine) introduce uncertainty about the magnitude of first-pass metabolism in the query.",
    "Human pharmacokinetic data for hydromorphone itself would resolve the remaining uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

